def card(work):
    repo = _tree(work / 'repo', {'util/slug.py': "def slugify(s):\n    return '-'.join(s.lower().split())\n"})

    def decide(candidates):
        exact = [c for c in candidates if c['fit'] >= 0.9 and c['maintained'] and (c['licence'] in ('MIT', 'Apache-2.0'))]
        if exact:
            return ('Adopt', exact[0]['name'])
        partial = [c for c in candidates if 0.6 <= c['fit'] < 0.9 and c['maintained']]
        if partial:
            return ('Extend', partial[0]['name'])
        weak = [c for c in candidates if 0.3 <= c['fit'] < 0.6]
        if len(weak) >= 2:
            return ('Compose', '+'.join((c['name'] for c in weak[:3])))
        return ('Build', '')

    def search_repo(word):
        return [str(p.relative_to(repo)) for p in repo.rglob('*.py') if f'def {word}' in p.read_text()]
    in_repo = search_repo('slugify')
    cases = {'exact': [{'name': 'pyslug', 'fit': 0.95, 'maintained': True, 'licence': 'MIT'}], 'exact_gpl': [{'name': 'gslug', 'fit': 0.95, 'maintained': True, 'licence': 'GPL-3.0'}], 'partial': [{'name': 'textkit', 'fit': 0.7, 'maintained': True, 'licence': 'MIT'}], 'weak': [{'name': 'a', 'fit': 0.4, 'maintained': True, 'licence': 'MIT'}, {'name': 'b', 'fit': 0.35, 'maintained': False, 'licence': 'MIT'}], 'none': []}
    verdicts = {k: decide(v)[0] for k, v in cases.items()}
    _w(work, 'decisions.json', {'repo_hits': in_repo, 'verdicts': verdicts})
    return [('repo searched first and finds existing slugify', in_repo == ['util/slug.py'], str(in_repo)), ('exact maintained MIT match -> Adopt', verdicts['exact'] == 'Adopt', verdicts['exact']), ('GPL exact match is not auto-adopted', verdicts['exact_gpl'] != 'Adopt', verdicts['exact_gpl']), ('partial -> Extend, weak pair -> Compose, none -> Build', (verdicts['partial'], verdicts['weak'], verdicts['none']) == ('Extend', 'Compose', 'Build'), str(verdicts))]

