def card(work):

    def buggy(xs):
        total = 0
        for x in xs:
            total += 100 // x
        return total

    def fails(xs):
        try:
            buggy(xs)
            return False
        except ZeroDivisionError:
            return True

    def ddmin(data):
        n = 2
        while len(data) >= 2:
            chunk = max(1, len(data) // n)
            subsets = [data[i:i + chunk] for i in range(0, len(data), chunk)]
            for s in subsets:
                if fails(s):
                    data, n = (s, 2)
                    break
            else:
                for i in range(len(subsets)):
                    comp = [x for j, s in enumerate(subsets) if j != i for x in s]
                    if fails(comp):
                        data, n = (comp, max(n - 1, 2))
                        break
                else:
                    if n >= len(data):
                        break
                    n = min(len(data), n * 2)
        return data
    big = list(range(1, 20))
    big.insert(11, 0)
    minimal = ddmin(big)

    def fixed(xs):
        return sum((100 // x for x in xs if x != 0))

    def regression(fn):
        try:
            return fn([5, 0]) == 20
        except ZeroDivisionError:
            return False
    _w(work, 'rootcause.json', {'original_len': len(big), 'minimal': minimal})
    return [('failure reproduced on the original 20 items', fails(big), str(len(big))), ('delta debugging shrinks to the planted [0]', minimal == [0], str(minimal)), ('regression test fails before the fix', not regression(buggy), 'red'), ('regression test passes after the fix', regression(fixed), 'green')]

